export function resolveMentions(
  body: string,
  members: readonly MemberWithUser[],
): readonly UserId[] {
  const byHandle = new Map<string, UserId>();
  for (const member of members) {
    // Read-only members cannot take part in a discussion, so pinging them
    // only produces an alert they can do nothing about.
    if (member.role === "viewer") continue;
    byHandle.set(handleOf(member), member.userId);
  }

  const resolved: UserId[] = [];
  const seen = new Set<UserId>();
  for (const handle of extractMentions(body)) {
    const userId = byHandle.get(handle);
    if (userId === undefined || seen.has(userId)) continue;
    seen.add(userId);
    resolved.push(userId);
  }

  return resolved;
}

input.new_string:
export function resolveMentions(
  body: string,
  members: readonly MemberWithUser[],
  options?: { excludeUserId?: UserId },
): readonly UserId[] {
  const byHandle = new Map<string, UserId[]>();
  for (const member of members) {
    // Removed and not-yet-active memberships are not mentionable. Role is
    // irrelevant: a viewer is still a member of the workspace.
    if (member.status !== "active" || member.archivedAt !== null) continue;
    const handle = handleOf(member);
    if (handle === "") continue;
    const ids = byHandle.get(handle) ?? [];
    ids.push(member.userId);
    byHandle.set(handle, ids);
  }

  const resolved: UserId[] = [];
  const seen = new Set<UserId>();
  for (const handle of extractMentions(body)) {
    for (const userId of byHandle.get(handle) ?? []) {
      if (userId === options?.excludeUserId || seen.has(userId)) continue;
      seen.add(userId);
      resolved.push(userId);
    }
  }

  return resolved;
}

