function isPastEditWindow(comment: Comment): boolean {
  // The window follows the last save: a typo fix a minute before the cut-off
  // must not lock the author out of correcting the correction.
  const posted = new Date(comment.updatedAt).getTime();
  return Date.now() - posted > EDIT_WINDOW_MS;
}

/**
 * Union of the ids the client already resolved (optimistic UI) and the ones
 * parsed out of the body server-side. The server list wins on disagreement.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await memberRepo.listMembers({
    orgId,
    limit: MENTION_LOOKUP_LIMIT,
    cursor: null,
  });

  const resolved = resolveMentions(body, members.items);
  const known = new Set(members.items.map((member) => member.userId));

  return [
    ...new Set([...resolved, ...clientProvided.filter((id) => known.has(id))]),
  ];
}

input.new_string:
function isPastEditWindow(comment: Comment): boolean {
  // Counted from the original post. An edit must not reopen the window.
  const posted = new Date(comment.createdAt).getTime();
  return Date.now() - posted > EDIT_WINDOW_MS;
}

/**
 * Mentions are exactly the active members whose handle appears in the body,
 * outside code, excluding the comment's author. Every member is scanned —
 * a workspace can be larger than one page.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  authorId: UserId,
): Promise<readonly UserId[]> {
  const members = [];
  let cursor: string | null = null;
  const seenCursors = new Set<string>();

  for (;;) {
    const page = await memberRepo.listMembers({
      orgId,
      status: "active",
      limit: MENTION_PAGE_SIZE,
      cursor,
    });
    members.push(...page.items);
    if (page.nextCursor === null || seenCursors.has(page.nextCursor)) break;
    seenCursors.add(page.nextCursor);
    cursor = page.nextCursor;
  }

  return resolveMentions(body, members, { excludeUserId: authorId });
}

